/**
 * Merge the harvested legal definitions with the authored editorial layer into the glossary
 * collection. SEO_ASTRO_PLAN.md §1027.
 *
 *   node scripts/build-glossary.mjs
 *
 * Inputs (both in data-raw/glossary/, both committed):
 *   definitions.json  generated by extract-glossary.mjs — verbatim wording text + UIN
 *   editorial.json    hand-authored plain-English gloss and "why it matters"
 *
 * Output: src/content/glossary/*.json — generated, never hand-edited, like every other
 * collection (CLAUDE.md).
 *
 * **The gate: a term is only written if it has an editorial layer.** A page carrying nothing
 * but a lifted legal definition is a thin page and adds nothing a policy PDF does not already
 * say. §9.4 puts the glossary early precisely because it is meant to be the *lowest-risk*
 * content on the site — that only holds if each page has something of ours on it.
 */
import { readFileSync, writeFileSync, mkdirSync, rmSync, existsSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const repoRoot = join(here, '..', '..')
const glossaryRaw = join(repoRoot, 'data-raw', 'glossary')
const outDir = join(here, '..', 'src', 'content', 'glossary')

const definitions = JSON.parse(readFileSync(join(glossaryRaw, 'definitions.json'), 'utf8'))
const editorialFile = JSON.parse(readFileSync(join(glossaryRaw, 'editorial.json'), 'utf8'))

// Keys starting with _ are notes to whoever edits the file, not terms.
const editorial = Object.fromEntries(
  Object.entries(editorialFile).filter(([key]) => !key.startsWith('_')),
)

const bySlug = new Map(definitions.map((d) => [d.slug, d]))

rmSync(outDir, { recursive: true, force: true })
mkdirSync(outDir, { recursive: true })

const written = []
const missingDefinition = []
const danglingRelated = []

for (const [slug, copy] of Object.entries(editorial)) {
  const source = bySlug.get(slug)

  // An editorial entry with no harvested definition would mean publishing our words as if
  // they were the policy's. Refuse rather than guess.
  if (!source) {
    missingDefinition.push(slug)
    continue
  }

  for (const related of copy.related ?? []) {
    if (!editorial[related]) danglingRelated.push(`${slug} → ${related}`)
  }

  written.push({
    slug,
    term: source.term,
    /** Verbatim from the wording. Never edit this — edit editorial.json instead. */
    definition: source.definition,
    source: source.source,
    plain: copy.plain,
    whyItMatters: copy.whyItMatters,
    // Only link terms that are actually published, or the mesh grows 404s.
    related: (copy.related ?? []).filter((r) => editorial[r]),
  })
}

for (const term of written) {
  writeFileSync(join(outDir, `${term.slug}.json`), JSON.stringify(term, null, 2) + '\n')
}

console.log(
  `[glossary] ${written.length} of ${definitions.length} harvested terms published ` +
    `(${definitions.length - written.length} awaiting an editorial layer)`,
)

if (missingDefinition.length > 0) {
  console.warn(
    `[glossary] ⚠ ${missingDefinition.length} editorial entr(ies) have no harvested definition ` +
      `and were skipped: ${missingDefinition.join(', ')}`,
  )
}

if (danglingRelated.length > 0) {
  console.warn(
    `[glossary] ⚠ related-term links pointing at unpublished terms, dropped: ` +
      danglingRelated.join(', '),
  )
}
